-- Post-upgrade validation (read only). Columns: check | actual | expected
select 'V1 users/profiles/google' as check_name, (select count(*) from auth.users) || ' / ' || (select count(*) from public.profiles) || ' / ' || (select count(distinct user_id) from auth.identities where provider = 'google') as actual, '8 / 8 / 6' as expected
union all select 'V2 characters/campaigns/members', (select count(*) from public.characters) || ' / ' || (select count(*) from public.campaigns) || ' / ' || (select count(*) from public.campaign_members), '7 / 2 / 8'
union all select 'V3 inventory rows / without inventory_id', (select count(*) from public.inventory_items) || ' / ' || (select count(*) from public.inventory_items where inventory_id is null), '76 / 0'
union all select 'V4 character inventories', (select count(*) from public.inventories where kind = 'character')::text, '7'
union all select 'V5 campaign governance', (select string_agg(preset || ':' || n, ',') from (select preset, count(*) n from public.campaign_governance group by 1) z), 'relaxed:2'
union all select 'V6 characters set up', (select count(*) from public.character_governance where setup_complete)::text, '7'
union all select 'V9 tables / no RLS / unpinned SECDEF', (select count(*) from pg_tables where schemaname = 'public') || ' / ' || (select count(*) from pg_tables where schemaname = 'public' and not rowsecurity) || ' / ' || (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prosecdef and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%')), '152 / 0 / 0'
union all select 'V10 policies count / hash', (select count(*) || ' / ' || md5(string_agg(format('%s.%s %s %s', schemaname, tablename, policyname, cmd), E'\n' order by schemaname, tablename, policyname)) from pg_policies where schemaname = 'public' or (schemaname = 'storage' and policyname like 'portraits%')), '170 / 91bd4664f2167ec4ba8e3357538b7efc'
union all select 'V11 realtime / storage policies', (select count(*) from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public') || ' / ' || (select count(*) from pg_policies where schemaname = 'storage' and tablename = 'objects'), '30 / 3'   -- 20261112000200 removed character_conditions from supabase_realtime (was 31)
union all select 'V12 bucket', (select format('%s public=%s %s %s', id, public, file_size_limit, allowed_mime_types) from storage.buckets where id = 'portraits'), 'portraits public=t 2097152 {image/jpeg,image/png,image/webp}'
union all select 'X legacy rows (spells/attacks/features/trackers/notes)', (select count(*) from public.spells) || '/' || (select count(*) from public.attacks) || '/' || (select count(*) from public.features) || '/' || (select count(*) from public.feature_trackers) || '/' || (select count(*) from public.notes), '36/21/73/9/35'
union all select 'X V6.2 constraints present', (select count(*) from pg_constraint where conname in ('characters_hp_current_check', 'characters_coins_check'))::text, '2'
union all select 'X admins kept', (select count(*) from public.profiles where role = 'admin')::text, '2'
union all select 'X event trigger ensure_rls', (select count(*) from pg_event_trigger where evtname = 'ensure_rls')::text, '1';
